-- إضافي وآمن: لا توجد عمليات DROP أو حذف بيانات. شغّل صراحة بعد مراجعة البيئة.
CREATE TABLE IF NOT EXISTS accounts (id varchar(36) NOT NULL PRIMARY KEY, open_id varchar(191) NOT NULL UNIQUE, name varchar(255) NOT NULL, email varchar(320), created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id varchar(36) NOT NULL PRIMARY KEY, account_id varchar(36) NOT NULL, token_hash varchar(64) NOT NULL UNIQUE, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY sessions_account_idx(account_id));
CREATE TABLE IF NOT EXISTS auth_states (id varchar(36) NOT NULL PRIMARY KEY, state_hash varchar(64) NOT NULL UNIQUE, nonce_hash varchar(64) NOT NULL, csrf_hash varchar(64) NOT NULL, redirect_uri varchar(2048) NOT NULL, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cases (id varchar(36) NOT NULL PRIMARY KEY, account_id varchar(36) NOT NULL, title varchar(160) NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY cases_owner_updated_idx(account_id,updated_at));
CREATE TABLE IF NOT EXISTS documents (id varchar(36) NOT NULL PRIMARY KEY, account_id varchar(36) NOT NULL, case_id varchar(36) NOT NULL, file_name varchar(255) NOT NULL, mime_type varchar(120) NOT NULL, size_bytes int NOT NULL, object_key varchar(255), page_count int, status varchar(20) NOT NULL, error_message varchar(255), deleted_at timestamp NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY docs_owner_case_idx(account_id,case_id));
CREATE TABLE IF NOT EXISTS source_segments (id varchar(36) NOT NULL PRIMARY KEY, account_id varchar(36) NOT NULL, case_id varchar(36) NOT NULL, document_id varchar(36) NOT NULL, page_number int NULL, segment_number int NOT NULL, content longtext NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY segments_owner_case_idx(account_id,case_id), KEY segments_document_idx(document_id));
CREATE TABLE IF NOT EXISTS analyses (id varchar(36) NOT NULL PRIMARY KEY, account_id varchar(36) NOT NULL, case_id varchar(36) NOT NULL, summary longtext NOT NULL, summary_sources json NOT NULL, events json NOT NULL, entities json NOT NULL, review_notes json NOT NULL, status varchar(20) NOT NULL DEFAULT 'ai_draft', created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY analysis_owner_case_idx(account_id,case_id,updated_at));
